+package decisiontest
+
+import (
+	"encoding/json"
+	"testing"
+
+	"github.com/ollama/ollama/decision"
+	"github.com/ollama/ollama/llm"
+)
+
+func TestCacheExpectation(t *testing.T) {
+	zero, half, one := 0.0, 0.5, 1.0
+	full, partial := 100, 1
+	for _, tt := range []struct {
+		name        string
+		expectation *CacheExpectation
+		cached      *int
+		wantErr     bool
