+}
+
+func pythonScalar(token json.Token) (string, error) {
+	switch v := token.(type) {
+	case nil:
+		return "null", nil
+	case bool:
+		return strconv.FormatBool(v), nil
+	case string:
+		var b strings.Builder
+		b.WriteByte('"')
+		for _, r := range v {
+			switch r {
+			case '"', '\\':
+				b.WriteByte('\\')
+				b.WriteRune(r)
+			case '\b':
+				b.WriteString(`\b`)
+			case '\f':
+				b.WriteString(`\f`)
+			case '\n':
+				b.WriteString(`\n`)
+			case '\r':
+				b.WriteString(`\r`)
+			case '\t':
+				b.WriteString(`\t`)
+			default:
+				if r < 0x20 {
+					fmt.Fprintf(&b, `\u%04x`, r)
+				} else {
+					b.WriteRune(r)
+				}
+			}
+		}
+		b.WriteByte('"')
+		return b.String(), nil
+	case json.Number:
+		if !strings.ContainsAny(string(v), ".eE") {
+			if v == "-0" {
+				return "0", nil
+			}
+			return string(v), nil
+		}
+		n, err := v.Float64()
+		if math.IsInf(n, 0) {
+			if n < 0 {
+				return "-Infinity", nil
+			}
+			return "Infinity", nil
+		}
+		if err != nil {
