+		}
+		if a := math.Abs(n); a >= 1e16 || (a != 0 && a < 1e-4) {
+			return strconv.FormatFloat(n, 'e', -1, 64), nil
+		}
+		s := strconv.FormatFloat(n, 'f', -1, 64)
+		if !strings.ContainsRune(s, '.') {
+			s += ".0"
+		}
+		return s, nil
+	default:
+		return "", fmt.Errorf("unsupported JSON value %T", token)
+	}
+}

